export function quotationLabel(language:UiLanguage,english:string):string {
 return uiText(language,english,bangla[english]??english);
}
export function quotationOptionLabels(language:UiLanguage,values:readonly string[]){
 return values.map(value=>({value,label:quotationLabel(language,value)}));
}
